public record CounterState(int Count = 0, bool Loading = false, string? Error = null);
public abstract record Intent;
public sealed record Increment : Intent;
public sealed record Refresh : Intent;
public sealed record LoadFailed(string Message) : Intent;

static CounterState Reduce(CounterState s, Intent i) => i switch {
    Increment      => s with { Count = s.Count + 1 },
    Refresh        => s with { Loading = true, Error = null },
    LoadFailed f   => s with { Loading = false, Error = f.Message },
    _              => s,
};
